#!/usr/bin/env python3
"""Vendor the CSS, JavaScript and fonts into internal/web/static/vendor/.

    python tools/vendor/fetch.py

Doables is meant to be something you run yourself, so it should not make every
page load fetch a third of a megabyte from a CDN that then knows the address of
everyone using it, and should not stop working on a network with no way out.
This downloads those assets, trims them, and writes them into the tree so they
are compiled into the binary.

The results are committed, so building needs nothing but Go. Run this only to
change a version: bump the numbers below, run it, check the screenshots still
match, and commit what changed.

Needs `python -m pip install "fonttools[woff]"` (fontTools and brotli).
"""

import re
import sys
import urllib.request
from pathlib import Path

from fontTools import subset

TABLER = "1.0.0"
ICONS = "3.19.0"
INTER = "4.1"

ROOT = Path(__file__).resolve().parents[2]
VENDOR = ROOT / "internal" / "web" / "static" / "vendor"
TEMPLATES = ROOT / "internal" / "web" / "templates"

CDN = f"https://cdn.jsdelivr.net/npm/@tabler/core@{TABLER}/dist"
ICON_CDN = f"https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@{ICONS}/dist"
INTER_CDN = "https://rsms.me/inter"


def fetch(url):
    print(f"  fetching {url}")
    # rsms.me turns away urllib's default user agent.
    req = urllib.request.Request(url, headers={"User-Agent": "doables-vendor/1.0"})
    with urllib.request.urlopen(req) as r:
        return r.read()


def used_icons():
    """Every ti-* class the templates actually use. An icon that is added to a
    template but not vendored would silently render as a blank square, so
    TestEveryIconIsVendored in internal/web fails when this is out of date."""
    names = set()
    for f in TEMPLATES.glob("*.html"):
        names |= set(re.findall(r"\bti-[a-z0-9-]+", f.read_text(encoding="utf-8")))
    return sorted(names)


def icon_css_and_font():
    """Tabler ships 5,800 icons: 844KB of font and 232KB of CSS naming them
    all. This app uses a few dozen, so keep those and throw the rest away."""
    css = fetch(f"{ICON_CDN}/tabler-icons.min.css").decode("utf-8")
    codepoints = dict(re.findall(r"\.(ti-[a-z0-9-]+):before\{content:\"\\([0-9a-f]+)\"\}", css))

    wanted = used_icons()
    missing = [n for n in wanted if n not in codepoints]
    if missing:
        sys.exit(f"no such icon in Tabler {ICONS}: {', '.join(missing)}")

    rules = "".join(f'.{n}:before{{content:"\\{codepoints[n]}"}}\n' for n in wanted)
    out = f"""/* Tabler Icons {ICONS} (MIT), subset to the {len(wanted)} icons Doables uses.
   Generated by tools/vendor/fetch.py - do not edit by hand. */
@font-face {{
  font-family: "tabler-icons";
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url("tabler-icons.woff2") format("woff2");
}}
.ti {{
  font-family: "tabler-icons" !important;
  speak: none;
  font-style: normal;
  font-weight: normal;
  font-variant: normal;
  text-transform: none;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}}
{rules}"""
    (VENDOR / "tabler-icons.css").write_text(out, encoding="utf-8", newline="\n")

    full = VENDOR / "tabler-icons-full.woff2"
    full.write_bytes(fetch(f"{ICON_CDN}/fonts/tabler-icons.woff2"))
    subset.main([
        str(full),
        "--unicodes=" + ",".join("U+" + codepoints[n] for n in wanted),
        "--flavor=woff2",
        # The icon font's ligature table is malformed enough that fontTools
        # refuses to walk it, and an icon font needs no shaping anyway: one
        # codepoint, one glyph.
        "--drop-tables+=GSUB,GPOS",
        "--output-file=" + str(VENDOR / "tabler-icons.woff2"),
    ])
    full.unlink()
    return len(wanted)


def inter():
    """Ship the variable font only, and unmodified: it covers every weight the
    UI asks for, and leaving it untouched keeps its licence simple. Upstream
    also serves 36 static cuts for browsers that cannot do variable fonts,
    which every browser has managed since 2018. The one file answers to both
    names, so stylesheets can go on asking for plain "Inter"."""
    (VENDOR / "InterVariable.woff2").write_bytes(fetch(f"{INTER_CDN}/font-files/InterVariable.woff2?v={INTER}"))
    (VENDOR / "inter.css").write_text(f"""/* Inter {INTER} (SIL Open Font License 1.1), variable font only.
   Generated by tools/vendor/fetch.py - do not edit by hand. */
@font-face {{
  font-family: Inter;
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("InterVariable.woff2") format("woff2");
}}
@font-face {{
  font-family: InterVariable;
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("InterVariable.woff2") format("woff2");
}}
""", encoding="utf-8", newline="\n")


def main():
    VENDOR.mkdir(parents=True, exist_ok=True)
    print("Tabler")
    (VENDOR / "tabler.min.css").write_bytes(fetch(f"{CDN}/css/tabler.min.css"))
    (VENDOR / "tabler.min.js").write_bytes(fetch(f"{CDN}/js/tabler.min.js"))
    print("Tabler Icons")
    n = icon_css_and_font()
    print("Inter")
    inter()
    print("licences")
    (VENDOR / "LICENSE-tabler.txt").write_bytes(
        fetch("https://raw.githubusercontent.com/tabler/tabler/master/LICENSE"))
    (VENDOR / "LICENSE-tabler-icons.txt").write_bytes(
        fetch("https://raw.githubusercontent.com/tabler/tabler-icons/master/LICENSE"))
    (VENDOR / "LICENSE-inter.txt").write_bytes(
        fetch("https://raw.githubusercontent.com/rsms/inter/master/LICENSE.txt"))

    print(f"\n{n} icons kept. Vendored into {VENDOR}:")
    total = 0
    for f in sorted(VENDOR.iterdir()):
        total += f.stat().st_size
        print(f"  {f.stat().st_size / 1024:8.1f} KB  {f.name}")
    print(f"  {total / 1024:8.1f} KB  total")


if __name__ == "__main__":
    main()
